SK.Sheets.rules = {
	["cm_per_unit"] = { id = "cm_per_unit", value = 0.25, unit = "cm/HU", source = "tuned", used_by = "katamath", note = "World scale of the stage. The map is never seen, so the stage runs at 4 Source units per cm: a 5 cm katamari is a 20-unit sphere, which Source physics handles well (smaller spheres jitter). Gravity is scaled to match (gravity_cm_s2)." },
	["catch_ratio"] = { id = "catch_ratio", value = 0.464, unit = "object sphere-equivalent diameter / katamari diameter", source = "research", used_by = "katamath", note = "Katamari's pickup rule: the katamari needs at least 10x the object's volume (10^(-1/3) = 0.464). Checked against 1466 of 1467 objects of the Katamari Damacy REROLL object table (community datamine, shookietea/reroll-notes). Used only for an object whose own catch size wasn't found in the player's Once Upon A KATAMARI." },
	["volume_rate"] = { id = "volume_rate", value = 0.8, unit = "x", source = "research", used_by = "katamath", note = "Default share of a caught object's volume added to the katamari (1270 of 1718 REROLL objects use 0.8). Each object's own rate from the player's Once Upon A KATAMARI wins when found." },
	["growth_mult"] = { id = "growth_mult", value = 1.0, unit = "x", source = "tuned", used_by = "katamath", note = "Extra multiplier on growth; 1 = the game's own rate." },
	["milestones_cm"] = { id = "milestones_cm", value = { 5, 6, 7, 8, 10, 12, 15, 20, 25, 30 }, unit = "cm", source = "tuned", used_by = "hud", note = "Next-size marks under the size display; reaching one plays the size-up sound." },
	["push_accel"] = { id = "push_accel", value = 12, unit = "diameters/s2", source = "tuned", used_by = "control", note = "Push acceleration, relative to the katamari size." },
