	["missing_ouak"] = { id = "missing_ouak", en = "Once Upon A KATAMARI isn't installed on this PC (Steam). Install it and press Play again in Melty: the objects you roll up, their sizes and the roll-up sounds all come from your copy.", es = "Once Upon A KATAMARI no está instalado en este PC (Steam). Instálalo y vuelve a pulsar Play en Melty: los objetos que enrollas, sus tamaños y los sonidos salen de tu copia.", where = "notice" },
	["missing_sh2"] = { id = "missing_sh2", en = "SILENT HILL 2 isn't installed on this PC (Steam). Install it and press Play again in Melty: James, the radio static and the music all come from your copy.", es = "SILENT HILL 2 no está instalado en este PC (Steam). Instálalo y vuelve a pulsar Play en Melty: James, la estática de la radio y la música salen de tu copia.", where = "notice" },
