	["ouak_unreadable"] = { id = "ouak_unreadable", en = "Your Once Upon A KATAMARI files couldn't be read ({reason}). Press Play again in Melty to retry.", es = "No se pudieron leer los archivos de tu Once Upon A KATAMARI ({reason}). Vuelve a pulsar Play en Melty para reintentarlo.", where = "notice" },
	["not_converted"] = { id = "not_converted", en = "The content from your games hasn't been read yet. Start the game from Melty so it can read Once Upon A KATAMARI and SILENT HILL 2.", es = "Todavía no se ha leído el contenido de tus juegos. Abre el juego desde Melty para que lea Once Upon A KATAMARI y SILENT HILL 2.", where = "notice" },
