SK.Sheets.systems = {
	["sheets"] = { id = "sheets", realm = "shared", file = "GM/gamemode/sk/sh_sheets.lua", summary = "Generated from sheets/*.json: every row as a Lua table, plus Rules lookups.", from_ouak = "-", from_sh2 = "-", gmod_api = "-", depends_on = {}, status = "planned" },
	["strings"] = { id = "strings", realm = "shared", file = "GM/gamemode/sk/sh_strings.lua", summary = "Text lookup in English or Spanish with {name} fill-ins.", from_ouak = "-", from_sh2 = "-", gmod_api = "GetConVarString gmod_language", depends_on = { "sheets" }, status = "planned" },
	["content"] = { id = "content", realm = "shared", file = "GM/gamemode/sk/sh_content.lua", summary = "Loads what the converter wrote on this PC (status, rules, object list, meshes) and decides per game whether its content is available, with the message to show when not.", from_ouak = "converter output", from_sh2 = "converter output", gmod_api = "file.Read GAME data_static", depends_on = { "sheets", "strings" }, status = "planned" },
	["katamath"] = { id = "katamath", realm = "shared", file = "GM/gamemode/sk/sh_katamath.lua", summary = "Pure Katamari maths with no Garry's Mod calls (unit conversion, catch rule, volume growth, size text, milestones, timer text), so the bench can run it headless.", from_ouak = "catch ratio and volume rate (via content)", from_sh2 = "-", gmod_api = "none (pure Lua)", depends_on = { "sheets" }, status = "planned" },
	["growth"] = { id = "growth", realm = "shared", file = "GM/gamemode/sk/sh_growth.lua", summary = "Applies katamath to entities: longest side, object volume, can-catch, grow.", from_ouak = "per-object catch size and volume rate", from_sh2 = "-", gmod_api = "OBBMins/OBBMaxs, PhysObj:GetVolume", depends_on = { "katamath", "content" }, status = "planned" },
	["sounds"] = { id = "sounds", realm = "shared", file = "GM/gamemode/sk/sh_sounds.lua", summary = "Registers the converted sounds as sound scripts; roll-up sound by object size; SH2 music, ambience and radio static as looping streams.", from_ouak = "roll-up, bump, dash, brake, size-up sounds", from_sh2 = "radio static, ambience, music", gmod_api = "sound.Add, EmitSound, CreateSound", depends_on = { "content", "sheets" }, status = "planned" },
	["ball"] = { id = "ball", realm = "shared", file = "GM/entities/entities/sk_ball.lua", summary = "The katamari: one physics sphere that resizes as it grows, keeps its collection, and is drawn with Katamari's own core when found (a plain sphere otherwise).", from_ouak = "the katamari core mesh and texture (when found)", from_sh2 = "-", gmod_api = "scripted entity, PhysicsInitSphere", depends_on = { "growth", "sounds", "meshes" }, status = "planned" },
	["mono"] = { id = "mono", realm = "shared", file = "GM/entities/entities/sk_mono.lua", summary = "One Katamari object: its converted mesh drawn with IMesh, convex physics from its hull, true size from the object table.", from_ouak = "object mesh, textures, size, hull", from_sh2 = "-", gmod_api = "scripted entity, PhysicsInitConvex, IMesh", depends_on = { "content", "meshes" }, status = "planned" },
	["player"] = { id = "player", realm = "server", file = "GM/gamemode/sk/sv_player.lua", summary = "The player is always rolling: spawns hidden and invulnerable, owns one katamari, rides along with it.", from_ouak = "-", from_sh2 = "-", gmod_api = "PlayerSpawn, PlayerLoadout, GodEnable, SetNoDraw", depends_on = { "ball", "content" }, status = "planned" },
	["control"] = { id = "control", realm = "shared", file = "GM/gamemode/sk/sh_control.lua", summary = "Movement keys push the katamari relative to the camera; Shift dashes; walking and weapons are blocked.", from_ouak = "-", from_sh2 = "-", gmod_api = "StartCommand, Move", depends_on = { "player", "ball" }, status = "planned" },
	["pickup"] = { id = "pickup", realm = "server", file = "GM/gamemode/sk/sv_pickup.lua", summary = "Finds objects touching the katamari and decides catch vs bump with the catch rule.", from_ouak = "catch rule", from_sh2 = "-", gmod_api = "ents.FindInSphere, Think", depends_on = { "ball", "growth", "attach", "sounds" }, status = "planned" },
	["attach"] = { id = "attach", realm = "server", file = "GM/gamemode/sk/sv_attach.lua", summary = "Turns a caught object into part of the katamari (no physics, parented where it touched); hides what is buried.", from_ouak = "-", from_sh2 = "-", gmod_api = "SetParent, PhysicsDestroy", depends_on = { "ball" }, status = "planned" },
	["stage"] = { id = "stage", realm = "server", file = "GM/gamemode/sk/sv_stage.lua", summary = "Builds the stage from the stage and tiers sheets: places Katamari objects by size in rings in the fog, runs the timer, judges the goal, restarts.", from_ouak = "which objects exist and their sizes", from_sh2 = "-", gmod_api = "ents.Create, timer, net", depends_on = { "mono", "content", "player", "growth" }, status = "planned" },
	["meshes"] = { id = "meshes", realm = "client", file = "GM/gamemode/sk/cl_meshes.lua", summary = "Builds IMesh objects and materials from converted mesh JSON and PNG textures, with a cache.", from_ouak = "object meshes and textures", from_sh2 = "James's mesh and textures, ground texture", gmod_api = "Mesh, CreateMaterial, Material", depends_on = { "content" }, status = "planned" },
	["james"] = { id = "james", realm = "client", file = "GM/gamemode/sk/cl_james.lua", summary = "Draws James Sunderland behind the katamari: the Source model compiled on the player's PC from his SH2 mesh, playing his own animations chosen from how the katamari moves, arms bent forward to push.", from_ouak = "-", from_sh2 = "James's skeletal mesh, skeleton, animations, textures (compiled to a model on the player's PC)", gmod_api = "ClientsideModel, ResetSequence, ManipulateBoneAngles, SetModelScale", depends_on = { "meshes", "ball", "content" }, status = "planned" },
	["camera"] = { id = "camera", realm = "client", file = "GM/gamemode/sk/cl_camera.lua", summary = "Katamari camera behind and above the ball, pulling back as it grows.", from_ouak = "-", from_sh2 = "-", gmod_api = "CalcView", depends_on = { "player" }, status = "planned" },
	["atmosphere"] = { id = "atmosphere", realm = "client", file = "GM/gamemode/sk/cl_atmosphere.lua", summary = "Silent Hill fog over everything, the sky cleared to fog colour, the ground plane, colour grading, and the music / ambience / radio static that rises as time runs out.", from_ouak = "-", from_sh2 = "ground texture, music, ambience, radio static", gmod_api = "SetupWorldFog, PreDrawSkyBox, RenderScreenspaceEffects, CreateSound", depends_on = { "sounds", "meshes", "stage" }, status = "planned" },
	["hud"] = { id = "hud", realm = "client", file = "GM/gamemode/sk/cl_hud.lua", summary = "Size display, goal, timer, intro and results, drawn with Katamari's own sprites and font when the converter found them.", from_ouak = "size display sprites and font", from_sh2 = "-", gmod_api = "HUDPaint, surface", depends_on = { "katamath", "content", "strings", "stage" }, status = "planned" },
	["hide"] = { id = "hide", realm = "shared", file = "GM/gamemode/sk/sh_hide.lua", summary = "Keeps Garry's Mod out of sight: every row of the hide sheet.", from_ouak = "-", from_sh2 = "-", gmod_api = "HUDShouldDraw, ScoreboardShow, PlayerBindPress, PlayerSpray, PlayerSwitchFlashlight, PlayerNoClip, CanPlayerSuicide", depends_on = { "sheets" }, status = "planned" },
	["pause"] = { id = "pause", realm = "client", file = "GM/gamemode/sk/cl_pause.lua", summary = "Our own pause menu in place of Garry's Mod's: resume, restart, quit.", from_ouak = "font (when found)", from_sh2 = "-", gmod_api = "OnPauseMenuShow, vgui", depends_on = { "strings", "stage" }, status = "planned" },
	["loading"] = { id = "loading", realm = "html", file = "addons/silent_katamari/html/silentkatamari/loading.html", summary = "Loading screen shown instead of Garry's Mod's while the stage loads.", from_ouak = "-", from_sh2 = "-", gmod_api = "sv_loadingurl asset://", depends_on = {}, status = "planned" },
	["conv_cli"] = { id = "conv_cli", realm = "tool", file = "CV/Program.cs", summary = "Commands: probe (report what is installed and readable), convert (write the content addon), play (convert when a game changed, then start Garry's Mod hidden behind our gamemode).", from_ouak = "-", from_sh2 = "-", gmod_api = "gmod.exe command line", depends_on = { "conv_steam", "conv_ouak", "conv_sh2", "conv_out" }, status = "planned" },
	["conv_steam"] = { id = "conv_steam", realm = "tool", file = "CV/Steam.cs", summary = "Finds Steam (registry, defaults), every library in libraryfolders.vdf, then appmanifest_<id>.acf -> installdir and buildid.", from_ouak = "install folder, buildid", from_sh2 = "install folder, buildid", gmod_api = "-", depends_on = {}, status = "planned" },
	["conv_ouak"] = { id = "conv_ouak", realm = "tool", file = "CV/Ouak/OuakReader.cs", summary = "Reads Katamari's Addressables bundles: the object table (sizes, catch sizes, volume rates), object meshes and textures, roll-up sounds, size display sprites and font.", from_ouak = "everything listed in extract rows of game ouak", from_sh2 = "-", gmod_api = "-", depends_on = { "conv_steam", "conv_out" }, status = "planned" },
	["conv_sh2"] = { id = "conv_sh2", realm = "tool", file = "CV/Sh2/Sh2Reader.cs", summary = "Checks SH2's containers (encryption flag, compression) and, when readable without any key, reads James's mesh, skeleton, animations and textures and the Wwise sounds.", from_ouak = "-", from_sh2 = "everything listed in extract rows of game sh2", gmod_api = "-", depends_on = { "conv_steam", "conv_out" }, status = "planned" },
	["conv_out"] = { id = "conv_out", realm = "tool", file = "CV/Out/ContentWriter.cs", summary = "Writes the private content addon (garrysmod/addons/silent_katamari_content): JSON meshes, PNG textures, WAV sounds, status.json last; stages to a temp folder and swaps.", from_ouak = "-", from_sh2 = "-", gmod_api = "addon folder layout, data_static", depends_on = {}, status = "planned" },
}
